"use client";

import { useId, useState, type ComponentProps } from "react";

import { LengthMeter } from "@rhs-ui/application/seo-fieldset/length-meter";
import { SearchPreview } from "@rhs-ui/application/seo-fieldset/preview";
import { DEFAULT_LABELS, cutOff, finishSlug, fitOf, fill, lengthOf, tidy, trail, typingSlug, type SeoFieldsetLabels, type SeoValue } from "@rhs-ui/application/seo-fieldset/seo";
import { Input } from "@rhs-ui/primitives/input";
import { InputGroup, InputGroupAddon, InputGroupInput } from "@rhs-ui/primitives/input-group";
import { Label } from "@rhs-ui/primitives/label";
import { Textarea } from "@rhs-ui/primitives/textarea";
import { cn } from "@/lib/utils";

export type { SeoFieldsetLabels, SeoValue } from "@rhs-ui/application/seo-fieldset/seo";

export interface SeoFieldsetProps extends Omit<ComponentProps<"div">, "defaultValue" | "onChange" | "children"> {
  /** The page's title, description and slug, when you control the fieldset. */
  value?: SeoValue;
  /** The text to begin with, when the fieldset keeps it itself. */
  defaultValue?: Partial<SeoValue>;
  /** Called with the whole value whenever a field changes. */
  onValueChange?: (value: SeoValue) => void;
  /** The address of the site: "https://northwind.example". The address line of the preview is built from it and the slug. */
  baseUrl: string;
  /** The site's name, on the first line of the preview. Default the host of `baseUrl`. */
  siteName?: string;
  /** The most characters of a title before it is cut off. Default 60. */
  titleLimit?: number;
  /** The most characters of a description before it is cut off. Default 160. */
  descriptionLimit?: number;
  /** The fewest characters that make a good title. Default 30, or the limit when that is lower. */
  titleMin?: number;
  /** The fewest characters that make a good description. Default 70, or the limit when that is lower. */
  descriptionMin?: number;
  /** What the preview shows, in grey, while the title is empty: the page's own heading. */
  fallbackTitle?: string;
  /** What the preview shows, in grey, while the description is empty: the start of the page. */
  fallbackDescription?: string;
  /** Show a field for the slug as well. It is always part of the preview. Default false. */
  editSlug?: boolean;
  /** A name for a plain form submit: the fields are sent as `<name>.title`, `<name>.description` and `<name>.slug`. */
  name?: string;
  /** Turn the whole fieldset off. */
  disabled?: boolean;
  /** The language of the character count and of the text. Default "en-US". */
  locale?: string;
  /** The words the fieldset says, for translation. */
  labels?: SeoFieldsetLabels;
}

/**
 * Two fields for what a page says to search engines, and a card that shows
 * how it would look as a result, updating as you type. A meter under each
 * field reads the length in characters against the range that is recommended
 * ("52 of 60, good", "Too long, cut off at 60") and the preview is cut
 * exactly where that limit says it would be. The address line is built from
 * the site address and the slug in the breadcrumb style of a result. An empty
 * field shows the fallback you pass, in grey, so the preview is never blank,
 * and the preview is named as an example for assistive technology.
 */
export function SeoFieldset({
  value,
  defaultValue,
  onValueChange,
  baseUrl,
  siteName,
  titleLimit = 60,
  descriptionLimit = 160,
  titleMin,
  descriptionMin,
  fallbackTitle,
  fallbackDescription,
  editSlug = false,
  name,
  disabled = false,
  locale = "en-US",
  labels,
  className,
  ...props
}: SeoFieldsetProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const base = useId();
  const ids = { title: `${base}-title`, description: `${base}-description`, slug: `${base}-slug`, titleHint: `${base}-title-hint`, descriptionHint: `${base}-description-hint`, titleMeter: `${base}-title-meter`, descriptionMeter: `${base}-description-meter` };
  const [own, setOwn] = useState<SeoValue>({ title: "", description: "", slug: "", ...defaultValue });
  const current = value ?? own;
  const minTitle = Math.min(titleMin ?? 30, titleLimit);
  const minDescription = Math.min(descriptionMin ?? 70, descriptionLimit);

  const titleCount = lengthOf(current.title, locale);
  const descriptionCount = lengthOf(current.description, locale);
  const titleFit = fitOf(titleCount, minTitle, titleLimit);
  const descriptionFit = fitOf(descriptionCount, minDescription, descriptionLimit);
  const where = trail(baseUrl, current.slug);
  const site = siteName ?? where.host;
  const titleEmpty = tidy(current.title) === "";
  const descriptionEmpty = tidy(current.description) === "";

  function change(patch: Partial<SeoValue>) {
    const next = { ...current, ...patch };
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  }

  // A field that turns good or long says so once, as a state: announcing the count at every key would talk over the typing.
  const stateOf = (fit: typeof titleFit, limit: number) => (fit === "long" ? fill(words.long, { limit }) : fit === "good" ? words.goodState : "");

  return (
    <div data-slot="seo-fieldset" className={cn("grid min-w-0 gap-6", className)} {...props}>
      <div className="grid gap-2">
        <Label htmlFor={ids.title}>{words.titleLabel}</Label>
        <p id={ids.titleHint} className="text-xs leading-5 text-muted-foreground">
          {words.titleHint}
        </p>
        <Input
          id={ids.title}
          name={name ? `${name}.title` : undefined}
          value={current.title}
          disabled={disabled}
          placeholder={fallbackTitle}
          autoComplete="off"
          aria-describedby={`${ids.titleHint} ${ids.titleMeter}`}
          onChange={(event) => change({ title: event.target.value })}
        />
        <LengthMeter id={ids.titleMeter} label={fill(words.meterLabel, { field: words.titleLabel })} count={titleCount} min={minTitle} limit={titleLimit} words={words} />
        <p role="status" className="sr-only">
          {stateOf(titleFit, titleLimit)}
        </p>
      </div>

      <div className="grid gap-2">
        <Label htmlFor={ids.description}>{words.descriptionLabel}</Label>
        <p id={ids.descriptionHint} className="text-xs leading-5 text-muted-foreground">
          {words.descriptionHint}
        </p>
        <Textarea
          id={ids.description}
          name={name ? `${name}.description` : undefined}
          value={current.description}
          disabled={disabled}
          placeholder={fallbackDescription}
          rows={3}
          aria-describedby={`${ids.descriptionHint} ${ids.descriptionMeter}`}
          onChange={(event) => change({ description: event.target.value })}
        />
        <LengthMeter id={ids.descriptionMeter} label={fill(words.meterLabel, { field: words.descriptionLabel })} count={descriptionCount} min={minDescription} limit={descriptionLimit} words={words} />
        <p role="status" className="sr-only">
          {stateOf(descriptionFit, descriptionLimit)}
        </p>
      </div>

      {editSlug ? (
        <div className="grid gap-2">
          <Label htmlFor={ids.slug}>{words.slugLabel}</Label>
          {/* On a phone the host would take half of the field, and the preview shows it anyway: it goes above the field, in small grey type, and the field gets all the room. */}
          <p aria-hidden="true" className="truncate text-xs leading-4 text-muted-foreground sm:hidden">
            {where.host}/
          </p>
          <InputGroup className={cn(disabled && "opacity-50")}>
            <InputGroupAddon className="hidden max-w-[55%] sm:flex">
              <span className="truncate">{where.host}/</span>
            </InputGroupAddon>
            <InputGroupInput
              id={ids.slug}
              name={name ? `${name}.slug` : undefined}
              value={current.slug}
              disabled={disabled}
              spellCheck={false}
              autoCapitalize="none"
              autoComplete="off"
              className="pl-3 sm:pl-0"
              onChange={(event) => change({ slug: typingSlug(event.target.value) })}
              onBlur={() => {
                // Tidied when the field is left, and reported only when the tidying changed something: a bare focus and blur is not an edit.
                const tidied = finishSlug(current.slug);
                if (tidied !== current.slug) change({ slug: tidied });
              }}
            />
          </InputGroup>
        </div>
      ) : name ? (
        <input type="hidden" name={`${name}.slug`} value={current.slug} />
      ) : null}

      <div className="grid gap-3">
        <SearchPreview
          siteName={site}
          host={where.host}
          parts={where.parts}
          url={where.url}
          title={cutOff(titleEmpty ? (fallbackTitle ?? words.untitled) : current.title, titleLimit, locale)}
          description={cutOff(descriptionEmpty ? (fallbackDescription ?? words.undescribed) : current.description, descriptionLimit, locale)}
          titleFallback={titleEmpty}
          descriptionFallback={descriptionEmpty}
          words={words}
        />
        {titleEmpty || descriptionEmpty ? <p className="text-xs leading-5 text-muted-foreground">{words.fallbackNote}</p> : null}
      </div>
    </div>
  );
}

import { IconAlertCircle, IconCheck, IconCircle } from "@rhs-ui/icons";
import { fill, fitOf, type Words } from "@rhs-ui/application/seo-fieldset/seo";
import { cn } from "@/lib/utils";

export interface LengthMeterProps {
  /** The id of the line that says where the length stands: the field points at it. */
  id: string;
  /** Names the meter for a screen reader: "Search title length". */
  label: string;
  count: number;
  /** The shortest length that is recommended. */
  min: number;
  /** The longest length before the text is cut off. */
  limit: number;
  words: Words;
}

/**
 * A length against a recommended range, in a bar and in words. The bar fills
 * as the text grows towards the limit, a tick marks where the recommended
 * range begins, and the line under it says the same in words with an icon: a
 * ring while it is empty or short, a check in range, a warning once the text
 * would be cut off.
 */
export function LengthMeter({ id, label, count, min, limit, words }: LengthMeterProps) {
  const fit = fitOf(count, min, limit);
  const sentence = fit === "empty" ? words.empty : fit === "long" ? fill(words.long, { limit }) : fill(fit === "good" ? words.good : words.short, { count, limit });
  const hint = fit === "long" ? fill(words.over, { count: count - limit }) : fill(words.range, { min, limit });
  const share = Math.min(1, count / limit);
  const Icon = fit === "long" ? IconAlertCircle : fit === "good" ? IconCheck : IconCircle;
  return (
    <div data-slot="seo-fieldset-meter" data-fit={fit} className="grid gap-2">
      <div role="meter" aria-label={label} aria-valuemin={0} aria-valuemax={limit} aria-valuenow={Math.min(count, limit)} aria-valuetext={sentence} className="relative h-1.5">
        <span className="absolute inset-0 overflow-hidden rounded-full bg-muted">
          <span
            aria-hidden="true"
            className={cn(
              "absolute inset-y-0 left-0 rounded-full transition-[width,background-color] duration-200 motion-reduce:transition-none",
              fit === "long" ? "bg-destructive" : fit === "good" ? "bg-foreground" : "bg-muted-foreground/60",
            )}
            style={{ width: `${share * 100}%` }}
          />
        </span>
        {/* Where the recommended range begins: a tick that stands out above and below the bar. */}
        <span aria-hidden="true" className="absolute -inset-y-[3px] w-px -translate-x-1/2 rounded-full bg-muted-foreground/50" style={{ left: `${(Math.min(min, limit) / limit) * 100}%` }} />
      </div>
      <div className="flex flex-wrap items-center justify-between gap-x-3 gap-y-1 text-xs leading-4">
        <p id={id} className={cn("flex items-center gap-1.5 tabular-nums", fit === "long" ? "font-medium text-destructive" : fit === "good" ? "font-medium text-foreground" : "text-muted-foreground")}>
          <Icon aria-hidden="true" className="size-3.5 shrink-0" />
          {sentence}
        </p>
        <p className={cn("tabular-nums", fit === "long" ? "font-medium text-destructive" : "text-muted-foreground")}>{hint}</p>
      </div>
    </div>
  );
}

import { Fragment } from "react";

import { Badge } from "@rhs-ui/primitives/badge";
import { initialOf, type Words } from "@rhs-ui/application/seo-fieldset/seo";
import { cn } from "@/lib/utils";

export interface SearchPreviewProps {
  /** The site's name, with its first letter in the round mark. */
  siteName: string;
  /** The address broken into the host and the parts of the path, for the breadcrumb line. */
  host: string;
  parts: readonly string[];
  /** The address as plain text, for a screen reader. */
  url: string;
  /** The title as the result shows it: already cut off at its limit. */
  title: string;
  /** The description as the result shows it: already cut off at its limit. */
  description: string;
  /** The field was empty and the text is the fallback. */
  titleFallback: boolean;
  descriptionFallback: boolean;
  words: Words;
}

/**
 * How a search result would look: the site and its address in a breadcrumb
 * line, the title as the headline and the description under it. It is an
 * example, and says so: a caption and a badge for the eye, and a name for
 * assistive technology that calls it an example. Text that comes from the
 * fallback is grey.
 */
export function SearchPreview({ siteName, host, parts, url, title, description, titleFallback, descriptionFallback, words }: SearchPreviewProps) {
  return (
    <figure data-slot="seo-fieldset-preview" aria-label={words.previewLabel} className="grid gap-3">
      <figcaption className="flex items-center justify-between gap-3">
        <span className="text-sm leading-5 font-medium">{words.previewTitle}</span>
        <Badge variant="outline">{words.previewBadge}</Badge>
      </figcaption>
      <div className="grid gap-3 rounded-xl border border-border bg-background p-4 shadow-xs sm:p-5">
        <div className="flex min-w-0 items-center gap-3">
          <span aria-hidden="true" className="grid size-8 shrink-0 place-items-center rounded-full border border-border bg-muted text-xs font-semibold text-foreground">
            {initialOf(siteName)}
          </span>
          <div className="grid min-w-0 gap-0.5">
            <p className="truncate text-sm leading-4 font-medium">{siteName}</p>
            <p className="truncate text-xs leading-4 text-muted-foreground">
              <span className="sr-only">{url}</span>
              <span aria-hidden="true">
                {host}
                {parts.map((part, index) => (
                  <Fragment key={`${index}-${part}`}>
                    <span className="px-1">&rsaquo;</span>
                    {part}
                  </Fragment>
                ))}
              </span>
            </p>
          </div>
        </div>
        <div className="grid gap-1">
          <p className={cn("text-lg leading-snug font-medium tracking-[-0.01em] break-words underline decoration-foreground/25 underline-offset-[3px]", titleFallback && "text-muted-foreground decoration-muted-foreground/25")}>{title}</p>
          <p className={cn("text-sm leading-relaxed break-words", descriptionFallback ? "text-muted-foreground/80" : "text-muted-foreground")}>{description}</p>
        </div>
      </div>
    </figure>
  );
}

/** What a page tells search engines about itself. */
export interface SeoValue {
  /** The headline of the search result. */
  title: string;
  /** The text under the headline. */
  description: string;
  /** The page's path under the site address: "journal/how-we-price-a-website". */
  slug: string;
}

/** The words the fieldset says, for translation. A `{name}` mark in a sentence is filled in. */
export interface SeoFieldsetLabels {
  /** The label of the title field. Default "Search title". */
  titleLabel?: string;
  /** The label of the description field. Default "Search description". */
  descriptionLabel?: string;
  /** The label of the slug field. Default "URL slug". */
  slugLabel?: string;
  /** The line under the title label. Default "The headline of your page in search results." */
  titleHint?: string;
  /** The line under the description label. Default "The text under the headline. Say what the page offers." */
  descriptionHint?: string;
  /** Names a meter for a screen reader; `{field}` is the label of its field. Default "{field} length". */
  meterLabel?: string;
  /** The meter while the text is shorter than recommended; `{count}` and `{limit}`. Default "{count} of {limit}, a little short". */
  short?: string;
  /** The meter while the length is in the recommended range; `{count}` and `{limit}`. Default "{count} of {limit}, good". */
  good?: string;
  /** The meter once the text would be cut off; `{limit}`. Default "Too long, cut off at {limit}". */
  long?: string;
  /** The meter while the field is empty. Default "Empty, the preview shows the fallback". */
  empty?: string;
  /** What the meter announces when the length turns good, as a state and not a count. Default "Good length". */
  goodState?: string;
  /** The recommended range, beside the meter; `{min}` and `{limit}`. Default "Aim for {min} to {limit}". */
  range?: string;
  /** How far over the limit, beside the meter; `{count}`. Default "{count} over". */
  over?: string;
  /** The caption of the preview card. Default "Search preview". */
  previewTitle?: string;
  /** The badge on the preview card. Default "Example". */
  previewBadge?: string;
  /** What a screen reader calls the preview. Default "Example of a search result; search engines may show something different". */
  previewLabel?: string;
  /** Under the preview while a field is empty. Default "Empty fields show the page's own text, in grey, as a search engine would fill them in." */
  fallbackNote?: string;
  /** The title in the preview when the field is empty and no `fallbackTitle` is passed. Default "Untitled page". */
  untitled?: string;
  /** The description in the preview when the field is empty and no `fallbackDescription` is passed. Default "No description yet. Search engines will pick a snippet from the page." */
  undescribed?: string;
}

export const DEFAULT_LABELS = {
  titleLabel: "Search title",
  descriptionLabel: "Search description",
  slugLabel: "URL slug",
  titleHint: "The headline of your page in search results.",
  descriptionHint: "The text under the headline. Say what the page offers.",
  meterLabel: "{field} length",
  short: "{count} of {limit}, a little short",
  good: "{count} of {limit}, good",
  long: "Too long, cut off at {limit}",
  empty: "Empty, the preview shows the fallback",
  goodState: "Good length",
  range: "Aim for {min} to {limit}",
  over: "{count} over",
  previewTitle: "Search preview",
  previewBadge: "Example",
  previewLabel: "Example of a search result; search engines may show something different",
  fallbackNote: "Empty fields show the page's own text, in grey, as a search engine would fill them in.",
  untitled: "Untitled page",
  undescribed: "No description yet. Search engines will pick a snippet from the page.",
} satisfies Required<SeoFieldsetLabels>;

export type Words = Required<SeoFieldsetLabels>;

/** Fills `{name}` marks in a sentence. A mark with no value stays as it is. */
export function fill(template: string, values: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (mark, key: string) => (key in values ? String(values[key]) : mark));
}

/** What a search engine reads: runs of spaces and line breaks become one space, and the ends are trimmed. */
export function tidy(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

/** The text as the characters a person sees: an emoji or an accented letter is one, not two or three code units. */
export function glyphs(text: string, locale: string): string[] {
  if (typeof Intl !== "undefined" && typeof Intl.Segmenter === "function") {
    return Array.from(new Intl.Segmenter(locale, { granularity: "grapheme" }).segment(text), (part) => part.segment);
  }
  return Array.from(text);
}

/** The length of a text in characters, after `tidy`. */
export function lengthOf(text: string, locale: string): number {
  return glyphs(tidy(text), locale).length;
}

/** The text as a search result shows it: whole when it fits, else cut after exactly `limit` characters and closed with an ellipsis. */
export function cutOff(text: string, limit: number, locale: string): string {
  const parts = glyphs(tidy(text), locale);
  return parts.length > limit ? `${parts.slice(0, limit).join("").trimEnd()}…` : parts.join("");
}

export type Fit = "empty" | "short" | "good" | "long";

/** Where a length stands against the recommended range: nothing yet, under it, inside it, or over the limit. */
export function fitOf(count: number, min: number, limit: number): Fit {
  if (count === 0) return "empty";
  if (count > limit) return "long";
  return count < min ? "short" : "good";
}

/** A slug while it is being typed: lower case, spaces and stray marks become a hyphen, slashes keep the path. Hyphens at the ends stay, so a word can be finished. */
export function typingSlug(raw: string): string {
  return raw
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/[^a-z0-9/]+/g, "-")
    .replace(/-{2,}/g, "-")
    .replace(/\/{2,}/g, "/")
    .replace(/^[-/]+/, "");
}

/** A finished slug: every segment trimmed of hyphens, and empty segments dropped. */
export function finishSlug(raw: string): string {
  return typingSlug(raw)
    .split("/")
    .map((segment) => segment.replace(/^-+|-+$/g, ""))
    .filter(Boolean)
    .join("/");
}

/** The address of a page in the breadcrumb style of a search result: the host, then each part of the path. */
export function trail(baseUrl: string, slug: string): { host: string; parts: string[]; url: string } {
  let host = baseUrl.replace(/^[a-z]+:\/\//i, "").replace(/\/.*$/, "");
  let path: string[] = [];
  try {
    const parsed = new URL(baseUrl);
    host = parsed.host;
    path = parsed.pathname.split("/").filter(Boolean);
  } catch {
    // An address without a scheme or a malformed one: the host is whatever came before the first slash.
  }
  const parts = [...path, ...slug.split("/").filter(Boolean)];
  return { host, parts, url: `${host}${parts.length ? `/${parts.join("/")}` : ""}` };
}

/** The first letter of a name, for the round mark before the site name. */
export function initialOf(name: string): string {
  return glyphs(name.trim(), "en-US")[0]?.toUpperCase() ?? "";
}
